<span class="line"><span style="--shiki-dark:#DCDCAA;--shiki-light:#795E26;">ip</span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;"> route</span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;"> add</span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;"> local</span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;"> 0.0.0.0/0</span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;"> dev</span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;"> lo</span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;"> table</span><span style="--shiki-dark:#B5CEA8;--shiki-light:#098658;"> 100</span></span>
